package dev.orbit.core.sync

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.launch
import java.time.Instant
import java.util.UUID

@JvmInline
value class ServerId(val value: String)

data class ItemStack(
    val itemId: String,
    val amount: Int,
    val nbt: ByteArray? = null,
) {
    init {
        require(amount in 1..64) { "amount must be in 1..64, was $amount" }
    }

    override fun equals(other: Any?): Boolean =
        other is ItemStack && itemId == other.itemId && amount == other.amount &&
            (nbt?.contentEquals(other.nbt) ?: (other.nbt == null))

    override fun hashCode(): Int = 31 * (31 * itemId.hashCode() + amount) + (nbt?.contentHashCode() ?: 0)
}

sealed interface SyncEvent {
    val serverId: ServerId
    val player: UUID
    val seq: Long
    val at: Instant

    data class SlotChanged(
        override val serverId: ServerId,
        override val player: UUID,
        override val seq: Long,
        override val at: Instant,
        val slot: Int,
        val stack: ItemStack?,
    ) : SyncEvent

    data class Cleared(
        override val serverId: ServerId,
        override val player: UUID,
        override val seq: Long,
        override val at: Instant,
    ) : SyncEvent
}

data class Inventory(val slots: Map<Int, ItemStack>) {
    fun apply(event: SyncEvent): Inventory = when (event) {
        is SyncEvent.SlotChanged ->
            if (event.stack == null) copy(slots = slots - event.slot)
            else copy(slots = slots + (event.slot to event.stack))
        is SyncEvent.Cleared -> EMPTY
    }

companion object {
        val EMPTY = Inventory(emptyMap())
    }
}

interface CursorStore {
    suspend fun cursor(server: ServerId, player: UUID): Long
    suspend fun advance(server: ServerId, player: UUID, seq: Long)
}

class SyncWorker(
    private val scope: CoroutineScope,
    private val cursors: CursorStore,
    private val sink: suspend (SyncEvent, Inventory) -> Unit,
    private val batchSize: Int = 256,
) {
    private val inbox = Channel<SyncEvent>(capacity = batchSize * 4)
    private val state = HashMap<Pair<ServerId, UUID>, Inventory>()

    fun events(): Flow<SyncEvent> = inbox.receiveAsFlow()

    suspend fun offer(event: SyncEvent) = inbox.send(event)

fun start() = scope.launch {
        val batch = ArrayList<SyncEvent>(batchSize)
        for (event in inbox) {
            batch += event
            if (batch.size >= batchSize || inbox.isEmpty) {
                flush(batch)
                batch.clear()
            }
        }
    }

    private suspend fun flush(batch: List<SyncEvent>) {
        for ((key, events) in batch.groupBy { it.serverId to it.player }) {
            val cursor = cursors.cursor(key.first, key.second)
            val fresh = events.filter { it.seq > cursor }.sortedBy { it.seq }
            if (fresh.isEmpty()) continue
            var inv = state[key] ?: Inventory.EMPTY
            for (e in fresh) {
                inv = inv.apply(e)
                sink(e, inv)
            }
            state[key] = inv
            cursors.advance(key.first, key.second, fresh.last().seq)
        }
    }
}

// Generates mcp-tools.json: an MCP tools/list result shaped like a GitHub-style server.
const str = (description: string, extra: Record<string, unknown> = {}) => ({ type: "string", description, ...extra });
const int = (description: string, extra: Record<string, unknown> = {}) => ({ type: "integer", description, ...extra });
const owner = str("Repository owner (user or organization login)");
const repo = str("Repository name without the owner");
const page = int("Page number for pagination, starting at 1", { minimum: 1, default: 1 });
const perPage = int("Results per page, at most 100", { minimum: 1, maximum: 100, default: 30 });
const tool = (name: string, description: string, properties: Record<string, unknown>, required: string[], readOnly: boolean) => ({
  name,
  description,
  inputSchema: { type: "object", properties, required, additionalProperties: false, $schema: "http://json-schema.org/draft-07/schema#" },
  annotations: { title: name.replace(/_/g, " "), readOnlyHint: readOnly },
});
const tools = [
  tool("get_file_contents", "Get the contents of a file or directory from a GitHub repository. Returns base64 for binary files.", { owner, repo, path: str("Path to the file or directory"), ref: str("Git ref: branch, tag or commit SHA. Defaults to the default branch.") }, ["owner", "repo", "path"], true),
  tool("create_or_update_file", "Create or update a single file in a repository. Requires the blob SHA when updating an existing file.", { owner, repo, path: str("Path where to create or update the file"), content: str("New file content, UTF-8"), message: str("Commit message"), branch: str("Branch to commit to"), sha: str("Blob SHA of the file being replaced, required for updates") }, ["owner", "repo", "path", "content", "message", "branch"], false),
  tool("search_code", "Search for code across GitHub repositories using the code search syntax, for example `language:kotlin repo:owner/name SyncWorker`.", { query: str("Search query using GitHub code search syntax"), sort: str("Sort field", { enum: ["indexed"] }), order: str("Sort order", { enum: ["asc", "desc"] }), page, perPage }, ["query"], true),
  tool("list_issues", "List issues in a repository with optional filters. Pull requests are excluded.", { owner, repo, state: str("Filter by state", { enum: ["open", "closed", "all"], default: "open" }), labels: { type: "array", items: { type: "string" }, description: "Only issues with all of these labels" }, since: str("ISO 8601 timestamp, only issues updated after it", { format: "date-time" }), page, perPage }, ["owner", "repo"], true),
  tool("create_issue", "Open a new issue in a repository.", { owner, repo, title: str("Issue title"), body: str("Issue body in GitHub Markdown"), assignees: { type: "array", items: { type: "string" }, description: "Logins to assign" }, labels: { type: "array", items: { type: "string" }, description: "Labels to apply" }, milestone: int("Milestone number") }, ["owner", "repo", "title"], false),
  tool("create_pull_request", "Create a pull request from a head branch into a base branch.", { owner, repo, title: str("Pull request title"), body: str("Pull request description"), head: str("Branch with your changes, or `user:branch` for forks"), base: str("Branch to merge into"), draft: { type: "boolean", description: "Create as draft", default: false } }, ["owner", "repo", "title", "head", "base"], false),
  tool("get_pull_request_diff", "Get the unified diff of a pull request.", { owner, repo, pullNumber: int("Pull request number") }, ["owner", "repo", "pullNumber"], true),
  tool("add_pull_request_review_comment", "Add a review comment to a specific line of a pull request diff.", { owner, repo, pullNumber: int("Pull request number"), path: str("Relative path of the file to comment on"), line: int("Line in the diff to comment on"), side: str("Side of the diff", { enum: ["LEFT", "RIGHT"] }), body: str("Comment text") }, ["owner", "repo", "pullNumber", "path", "line", "body"], false),
  tool("list_workflow_runs", "List GitHub Actions workflow runs for a repository, newest first.", { owner, repo, workflowId: str("Workflow file name or numeric ID"), branch: str("Only runs on this branch"), status: str("Run status", { enum: ["queued", "in_progress", "completed", "failure", "success"] }), page, perPage }, ["owner", "repo"], true),
  tool("get_job_logs", "Download logs for a workflow job. Large logs are truncated to the last N lines.", { owner, repo, jobId: int("Job ID"), tailLines: int("Number of lines from the end to return", { default: 500 }) }, ["owner", "repo", "jobId"], true),
];
await Bun.write(new URL("./mcp-tools.json", import.meta.url), JSON.stringify({ tools }, null, 2) + "\n");

def resolve_rules(rules, files):
    """Return the rules whose globs match any of the files."""
    matched = []
    for rule in rules:
        if any(fnmatch.fnmatch(path, glob) for glob in rule.globs for path in files):
            matched.append(rule)
    return sorted(matched, key=lambda rule: rule.path)
